	ingress  http.Handler
	yaml     string
	revision string
	jobs     []sourceJob
}

type manager struct {
	ctx       context.Context
	db        *storage.DB
	path      string
	bootstrap *config.Config
	current   atomic.Pointer[managedSnapshot]
	blocked   atomic.Bool
