/* Reuse the runtime's restrained palette. The management surface makes
   authority and unsaved state explicit rather than relying on status color. */
:root {
  font:
    16px/1.55 system-ui,
    -apple-system,
    sans-serif;
  color: #192e40;
  background: #fff;
  --ink: #192e40;
  --muted: #4e6477;
  --blue: #173e67;
  --line: #c5d2de;
  --paper: #eef3f7;
  --amber: #a34b14;
}
* {
  box-sizing: border-box;
}
body {
  margin: 0;
}
a {
  color: var(--blue);
  text-underline-offset: 4px;
}
::selection {
  background: #dfeaf4;
  color: #102e4e;
}
:focus-visible {
  outline: 3px solid var(--amber);
  outline-offset: 3px;
}
header {
  display: flex;
  align-items: center;
  flex-wrap: wrap;
  gap: 18px;
  padding: 14px 28px;
  background: var(--blue);
  color: white;
}
header a {
  color: #e0eaf4;
  text-decoration: none;
  padding: 8px 0;
}
header a[aria-current="page"] {
  color: #fff;
  text-decoration: underline;
  text-decoration-thickness: 2px;
}
header nav {
  display: flex;
  flex-wrap: wrap;
  gap: 20px;
  margin-left: auto;
}
.brand {
  font-size: 1.5rem;
  font-weight: 750;
  color: #fff;
}
main {
  max-width: 1180px;
  margin: auto;
  padding: 28px;
}
h1 {
  font:
    500 2.25rem/1.2 Charter,
