    serif;
  margin: 12px 0;
  color: #102e4e;
}
h2 {
  font-size: 1.15rem;
  margin: 30px 0 12px;
}
h3 {
  font-size: 1rem;
}
p {
  max-width: 74ch;
  margin: 0 0 14px;
}
button,
input,
select,
textarea {
  font: inherit;
  color: var(--ink);
  border: 1px solid var(--line);
  border-radius: 6px;
  background: #fff;
  min-height: 44px;
  padding: 9px 12px;
  max-width: 100%;
}
button {
  cursor: pointer;
  font-weight: 600;
}
button:hover {
  background: var(--paper);
  border-color: var(--blue);
}
button:disabled {
  opacity: 0.6;
  cursor: wait;
}
.primary {
  background: var(--blue);
  color: #fff;
}
.primary:hover {
  background: #102e4e;
  color: #fff;
}
.danger {
  color: #9a292d;
  border-color: #9a292d;
}
label {
  display: block;
  margin: 12px 0 6px;
  font-size: 0.875rem;
  font-weight: 600;
}
input:not([type="checkbox"]),
textarea {
  width: 100%;
}
input,
textarea {
  caret-color: var(--blue);
}
input::placeholder {
  color: var(--muted);
}
textarea,
pre {
  font:
    0.8125rem/1.6 ui-monospace,
    SFMono-Regular,
    Consolas,
    monospace;
}
textarea {
  resize: vertical;
  min-height: 240px;
}
pre {
  white-space: pre-wrap;
  overflow-wrap: anywhere;
  max-height: 500px;
