/* The guide gives one decision the full working area; the advanced editor
   keeps its existing layout rather than competing with first-run controls. */
.setup-heading {
  display: flex;
  align-items: start;
  justify-content: space-between;
  gap: 24px;
  margin: 28px 0;
}
.setup-heading h2 {
  margin: 0 0 8px;
  font-size: 1.5rem;
}
.setup-steps {
  display: grid;
  grid-template-columns: repeat(3, minmax(0, 1fr));
  list-style: none;
  padding: 0;
  margin: 0 0 32px;
  border-bottom: 1px solid var(--line);
}
.setup-steps li {
  padding: 12px;
  color: var(--muted);
}
.setup-steps [aria-current="step"] {
  color: var(--blue);
  background: var(--paper);
  box-shadow: inset 0 -2px var(--blue);
  font-weight: 650;
}
#setup-form {
  max-width: 880px;
}
#setup-form fieldset {
  border: 0;
  padding: 0;
  margin: 0;
  min-width: 0;
}
#setup-form legend {
  padding: 0;
  margin-bottom: 12px;
  font-size: 1.25rem;
  font-weight: 650;
}
#setup-form .fields {
  margin: 24px 0 16px;
}
#setup-form .row {
  margin-top: 24px;
}
#setup-credential-optional {
  font-weight: 400;
}
.setup-summary {
  display: grid;
  grid-template-columns: 140px minmax(0, 1fr);
  gap: 12px 20px;
  margin: 12px 0 24px;
}
.setup-summary dt {
  color: var(--muted);
}
.setup-summary dd {
  margin: 0;
  overflow-wrap: anywhere;
}
.setup-test {
  padding: 20px 0;
  border-block: 1px solid var(--line);
  margin-top: 28px;
}
.setup-test h3 {
  margin: 0 0 8px;
}
#setup-test-result {
  margin-top: 16px;
  overflow-wrap: anywhere;
}
#setup-status:not(:empty) {
  padding: 16px;
  background: var(--paper);
}
#setup-start:disabled {
  cursor: not-allowed;
}
[aria-busy="true"] {
  cursor: progress;
}
[hidden] {
  display: none !important;
}

.fields {
  grid-template-columns: 1fr;
}
.setup-heading {
  display: block;
}
.setup-steps {
  font-size: 0.875rem;
  margin-bottom: 24px;
}
.setup-steps li {
  padding: 10px 6px;
}
.setup-summary {
  grid-template-columns: 1fr;
  gap: 4px;
}
.setup-summary dd {
  margin-bottom: 12px;
}

