    for (const [i, row] of (report.results || []).entries())
      $("setup-test-result").append(el("p", `${i === 0 ? "Synthetic incident" : "Synthetic routine event"}: ${row.status === "ok" ? `${row.category} → ${row.outcome} · ${row.latency_ms} ms` : "No valid answer"}.`));
