#setup-form {
  max-width: 100%;
}
#setup-form [data-setup-step="0"],
#setup-form [data-setup-step="1"] {
  max-width: 880px;
}

.setup-review {
  display: grid;
  grid-template-columns: 1fr 1fr;
  gap: 40px;
  margin-top: 20px;
  padding-bottom: 24px;
  border-bottom: 1px solid var(--line);
}
.setup-review > * {
  min-width: 0;
}
.setup-test {
  padding: 20px;
  background: var(--paper);
}
.setup-test p {
  font-size: 0.875rem;
}

.setup-review {
  grid-template-columns: 1fr;
  gap: 20px;
}
.setup-test {
  padding: 16px;
}
.setup-summary {
  grid-template-columns: 1fr;

