    !doc.filter?.length &&
    !Object.keys(doc.agents || {}).length &&
    !Object.keys(doc.interpret_by_type || {}).length
  );
}
function providerFields() {
  const required = ["liquid-d1", "typesafe"].includes(
    $("setup-provider").value,
  );
  $("setup-env").required = required;
  $("setup-credential-optional").hidden = required;
}
function loadSetup(doc) {
  setupState.base = doc;
  setupState.dirty = false;
  setupState.candidate = "";
  invalidateSetupTest();
  $("setup-status").textContent = "";
  $("setup-guide").hidden = false;
  $("advanced-config").hidden = true;
  const supported = guideSupports(doc);
  $("setup-unavailable").hidden = supported;
  $("setup-workflow").hidden = !supported;
  if (!supported) return;
  const model = doc.models?.[doc.interpret?.model] || {};
  const example = model.model === "replace-with-your-model";
  const source = doc.sources?.[0];
  $("setup-provider").value = example
    ? "liquid-d1"
    : model.provider || "liquid-d1";
  $("setup-model").value = example ? "" : model.model || "";
  $("setup-url").value = example ? "" : model.base_url || "";
  $("setup-env").value = model.api_key_env || "";
  $("setup-name").value = source?.name || "service-monitor";
  // Renaming an existing journal would start a new tail and lose its position.
  $("setup-name").disabled = !!source;
  $("setup-units").value = (source?.units || []).join(", ");
  $("setup-priority").value = source?.priority || "warning";
  $("setup-every").value = source?.every || "30s";
