"use strict";
const assert = require("node:assert/strict");
const fs = require("node:fs/promises");
const os = require("node:os");
const path = require("node:path");
const { spawn } = require("node:child_process");
const { once } = require("node:events");
const delay = ms => new Promise(resolve => setTimeout(resolve, ms));
(async () => {
  let input = "";
  for await (const part of process.stdin) input += part;
  const access = JSON.parse(input);
  input = "";
  assert.ok(process.env.MRMR_CHROME, "Chrome path is required");
  const profile = await fs.mkdtemp(path.join(os.tmpdir(), "mrmr-deploy-browser-"));
  const chrome = spawn(process.env.MRMR_CHROME, ["--headless", "--disable-gpu", "--no-first-run", "--remote-debugging-port=0", `--user-data-dir=${profile}`, "about:blank"], { stdio: "ignore" });
  let socket;
  const waiting = new Map();
  try {
    let port;
    for (let i = 0; i < 100; i++) {
      try { port = (await fs.readFile(path.join(profile, "DevToolsActivePort"), "utf8")).split("\n")[0]; break; }
      catch { await delay(50); }
    }
    assert.ok(port, "Chrome did not start");
    const pages = await (await fetch(`http://127.0.0.1:${port}/json/list`)).json();
    socket = new WebSocket(pages.find(p => p.type === "page").webSocketDebuggerUrl);
    await new Promise((resolve, reject) => { socket.onopen = resolve; socket.onerror = reject; });
    let sequence = 0;
    const errors = [];
    socket.onmessage = e => {
      const msg = JSON.parse(e.data);
      if (msg.id) {
        const job = waiting.get(msg.id);
        if (!job) return;
        waiting.delete(msg.id); clearTimeout(job.timer);
        if (msg.error) job.reject(Error("Browser command failed")); else job.resolve(msg.result);
      } else if (msg.method === "Runtime.exceptionThrown") errors.push("Browser script error");
    };
    const rpc = (method, params = {}) => new Promise((resolve, reject) => {
      const id = ++sequence;
      const timer = setTimeout(() => { waiting.delete(id); reject(Error("Browser command timed out")); }, 10000);
      waiting.set(id, { resolve, reject, timer });
      socket.send(JSON.stringify({ id, method, params }));
    });
    const evaluate = async expression => {
      const result = await rpc("Runtime.evaluate", { expression, awaitPromise: true, returnByValue: true });
      if (result.exceptionDetails) throw Error("Browser evaluation failed");
      return result.result.value;
    };
    const until = async expression => {
      for (let i = 0; i < 100; i++) { if (await evaluate(expression)) return; await delay(50); }
      throw Error("Browser state did not become ready");
    };
    await rpc("Runtime.enable"); await rpc("Page.enable");
    await rpc("Page.navigate", { url: access.url });
    await until("!!document.getElementById('login-form')");
    await evaluate(`document.getElementById('token').value=${JSON.stringify(access.token)};document.getElementById('login-form').requestSubmit()`);
    access.token = "";
    await until("!document.getElementById('app').hidden");
    await evaluate("location.hash='configure'");
    await delay(100);
    assert.equal(await evaluate("document.getElementById('setup-provider').value"), "liquid-d1");
    assert.equal(await evaluate("document.getElementById('setup-env').value"), "MRMR_D1_API_KEY");
    assert.equal(await evaluate("document.getElementById('setup-name').value"), "Plex");
    assert.equal(await evaluate("document.getElementById('setup-units').value"), "plexmediaserver.service");
    assert.ok(await evaluate("document.getElementById('setup-name').disabled && document.getElementById('setup-start').disabled"));
    const revision = await evaluate("state.config.revision");
    // Stay on the read-only model/source steps: no compose, test, save, or activation.
    for (const width of [390, 1440]) {
      await rpc("Emulation.setDeviceMetricsOverride", { width, height: 1000, deviceScaleFactor: 1, mobile: width < 600 });
      for (const step of [0, 1]) {
        if (step === 1) await evaluate("document.getElementById('setup-next-model').click()");
        else await evaluate("document.getElementById('setup-back-model').click()");
        await until(`!document.querySelector('[data-setup-step="${step}"]').hidden`);
        assert.ok(await evaluate("document.documentElement.scrollWidth<=innerWidth+1"), "Remote UI overflows");
        const shot = await rpc("Page.captureScreenshot", { format: "png", captureBeyondViewport: true });
        await fs.writeFile(path.join(__dirname, `remote-setup-${step}-${width}.png`), Buffer.from(shot.data, "base64"), { mode: 0o600 });
      }
    }
    assert.equal(await evaluate("state.config.revision"), revision);
    assert.equal(await evaluate("state.dirty"), false);
    await evaluate("document.getElementById('logout').click()");
    assert.equal(await evaluate("document.getElementById('setup-model').value"), "");
    assert.equal(await evaluate("document.getElementById('yaml').value"), "");
    assert.deepEqual(errors, []);
    console.log("Remote browser: guided model/source screens verified at 390px and 1440px; no config writes; Lock cleared private fields");
  } finally {
    for (const job of waiting.values()) clearTimeout(job.timer);
    if (socket) socket.close();
    const ended = once(chrome, "exit");
    chrome.kill("SIGTERM");
    await Promise.race([ended, delay(2000).then(() => chrome.kill("SIGKILL"))]);
    await fs.rm(profile, { recursive: true, force: true });
  }
})().catch(error => { console.error(error.message); process.exitCode = 1; });

