    } catch (err) {
      notice(
        err.name === "AbortError"
          ? "Request timed out. Refresh runtime state before retrying a change."
          : err.message,
      );
    } finally {
      b.disabled = false;
      if (id === "setup-start") refreshSetupStart();
    }
  });
}
