}
#setup-form fieldset {
  border: 0;
  padding: 0;
  margin: 0;
  min-width: 0;
}
#setup-form legend {
  padding: 0;
  margin-bottom: 12px;
  font-size: 1.25rem;
  font-weight: 650;
}
#setup-form .fields {
  margin: 24px 0 16px;
}
#setup-form .row {
  margin-top: 24px;
}
#setup-credential-optional {
  font-weight: 400;
}
.setup-summary {
  display: grid;
  grid-template-columns: 140px minmax(0, 1fr);
  gap: 12px 20px;
  margin: 12px 0 24px;
}
.setup-summary dt {
  color: var(--muted);
}
.setup-summary dd {
  margin: 0;
  overflow-wrap: anywhere;
}
.setup-review {
  display: grid;
  grid-template-columns: 1fr 1fr;
  gap: 40px;
  margin-top: 20px;
  padding-bottom: 24px;
  border-bottom: 1px solid var(--line);
}
.setup-review > * {
  min-width: 0;
}
.setup-test {
  padding: 20px;
  background: var(--paper);
}
.setup-test p {
  font-size: 0.875rem;
}
.setup-test h3 {
  margin: 0 0 8px;
}
#setup-test-result {
  margin-top: 16px;
  overflow-wrap: anywhere;
}
#setup-status:not(:empty) {
  padding: 16px;
  background: var(--paper);
}
#setup-start:disabled {
  cursor: not-allowed;
}
[aria-busy="true"] {
  cursor: progress;
}
[hidden] {
  display: none !important;
}
@media (max-width: 700px) {
  header {
    padding: 12px 16px;
    gap: 12px;
  }
  header nav {
    order: 3;
    width: 100%;
    margin: 0;
    gap: 12px;
    font-size: 0.875rem;
  }
  header nav a {
    display: flex;
    align-items: center;
    min-height: 44px;
  }
  main {
    padding: 20px 16px;
  }
  .fields {
    grid-template-columns: 1fr;
  }
  .setup-heading {
    display: block;
  }
  .setup-steps {
    font-size: 0.875rem;
    margin-bottom: 24px;
  }
  .setup-steps li {
    padding: 10px 6px;
  }
  .setup-review {
    grid-template-columns: 1fr;
    gap: 20px;
  }
  .setup-test {
    padding: 16px;
  }
  .setup-summary {
    grid-template-columns: 1fr;
    gap: 4px;
  }
  .setup-summary dd {
    margin-bottom: 12px;
  }
  h1 {
    font-size: 2rem;
  }
  .row > * {
    min-width: 0;
  }
  .row input {
    min-width: 100%;
  }
  button {
    white-space: normal;
  }
  pre {
    padding: 12px;
  }
  .heading {
    align-items: start;
  }
  #notice {
    overflow-wrap: anywhere;
  }
}
